    {(t) => (
      <li
        ref={s.itemRef(t.id)}
        class={() => (s.isOverKey(t.id) ? `drop-${s.overEdge()}` : '')}
        data-active={() => s.isActive(t.id)}
      >
        {t.title}
      </li>
    )}
  </For>
