import { signal } from '@pyreon/reactivity'
import { useFileDrop } from '@pyreon/dnd'

const Avatar = () => {
  const error = signal('')
  const drop = useFileDrop({
    accept: ['image/*'],
    maxFiles: 1,
    onDrop: (files) => upload(files[0]!),
    onReject: (_files, reason) =>
      error.set(reason === 'accept' ? 'Images only' : 'One file at a time'),
  })
  return (
    <div ref={drop.ref} class={() => (drop.isOver() ? 'zone over' : 'zone')}>
      Drop a photo <span role="alert">{error()}</span>
    </div>
  )
}
